import React, { useState, useEffect } from 'react';
import { useNavigate, useLocation, Link } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { getUnreadCount } from '../services/api';

export default function Navbar() {
  const { user, signOut } = useAuth();
  const navigate = useNavigate();
  const location = useLocation();
  const [unread, setUnread] = useState(0);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    if (user?.email) {
      getUnreadCount(user.email).then(r => setUnread(r.data.count)).catch(() => {});
    }
  }, [user, location.pathname]);

  const logout = () => { signOut(); navigate('/login'); };
  const active = (path) => location.pathname === path ? 'nav-link active' : 'nav-link';

  if (!user) return null;

  return (
    <nav className="navbar">
      <Link to="/dashboard" className="brand">⚡ InternHub</Link>
      <div style={{ display: 'flex', alignItems: 'center', gap: '0.1rem', flexWrap: 'wrap' }}>
        {user.role === 'STUDENT' && (
          <>
            <Link to="/dashboard"         className={active('/dashboard')}>Explore</Link>
            <Link to="/recommendations"   className={active('/recommendations')}>✨ For You</Link>
            <Link to="/my-applications"   className={active('/my-applications')}>Applications</Link>
            <Link to="/saved"             className={active('/saved')}>Saved</Link>
            <Link to="/ai-resume"         className={active('/ai-resume')}>🤖 Resume</Link>
            <Link to="/referral"          className={active('/referral')}>🏆 Rewards</Link>
            <Link to="/profile"           className={active('/profile')}>Profile</Link>
            <Link to="/notifications" className={active('/notifications')}
              style={{ position: 'relative', display: 'flex', alignItems: 'center' }}>
              🔔 {unread > 0 && <span className="notif-badge">{unread}</span>}
            </Link>
          </>
        )}
        {user.role === 'ADMIN' && (
          <>
            <Link to="/admin"                className={active('/admin')}>Dashboard</Link>
            <Link to="/admin/internships"    className={active('/admin/internships')}>Internships</Link>
            <Link to="/admin/applications"   className={active('/admin/applications')}>Applications</Link>
            <Link to="/admin/users"          className={active('/admin/users')}>Users</Link>
          </>
        )}
        <span style={{ color: 'var(--text2)', fontSize: '0.8rem', margin: '0 6px' }}>
          Hi, {user.name?.split(' ')[0]}
        </span>
        <button className="nav-btn" onClick={logout}>Logout</button>
      </div>
    </nav>
  );
}
